public class MaximoGenerico {
    public static <T extends Comparable<T>> T maximo(T[] arreglo) {
        if (arreglo == null || arreglo.length == 0) return null;
        T max = arreglo[0];
        for (int i = 1; i < arreglo.length; i++) {
            if (arreglo[i].compareTo(max) > 0) {
                max = arreglo[i];
            }
        }
        return max;
    }

    public static void main(String[] args) {
        Integer[] numeros = {3, 7, 1, 9, 4};
        String[] palabras = {"Ana", "Carlos", "Beatriz"};

        System.out.println("Máximo número: " + maximo(numeros));
        System.out.println("Máximo texto: " + maximo(palabras));
    }
}

